package web

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// ttsItem is one spoken curriculum section: the manifest key matches the mp3
// file generated by tts/generate.py, served from disk at /tts/full/{file}.
// File is "<slug>/<name>.mp3" and doubles as the URL fragment.
type ttsItem struct {
	N     int    `json:"n"`
	Title string `json:"title"`
	File  string `json:"file"`
}

type ttsTrack struct {
	Key   string
	Name  string
	Items []ttsItem
}

type ttsView struct {
	Voice  string
	Tracks []ttsTrack
}

//go:embed tts/manifest.json
var ttsManifest []byte

func ttsData() (ttsView, error) {
	var raw struct {
		Voice  string `json:"voice"`
		Tracks map[string]struct {
			Name  string    `json:"name"`
			Items []ttsItem `json:"items"`
		} `json:"tracks"`
	}
	if err := json.Unmarshal(ttsManifest, &raw); err != nil {
		return ttsView{}, fmt.Errorf("parse tts manifest: %w", err)
	}
	// Render tracks in curriculum navbar order, filling from the manifest
	// keyed by slug ("go", "typescript", ...).
	view := ttsView{Voice: raw.Voice}
	g, _ := findGroup("curriculum")
	for _, item := range g.Items {
		slug := strings.TrimPrefix(item.URL, "/curriculum/")
		if slug == "" {
			continue
		}
		src, ok := raw.Tracks[slug]
		if !ok {
			continue
		}
		view.Tracks = append(view.Tracks, ttsTrack{
			Key:   slug,
			Name:  src.Name,
			Items: src.Items,
		})
	}
	if len(view.Tracks) == 0 {
		return ttsView{}, fmt.Errorf("tts manifest has no matching tracks")
	}
	return view, nil
}

func handleTTS(w http.ResponseWriter, r *http.Request) {
	view, err := ttsData()
	if err != nil {
		log.Printf("tts: %v", err)
		Render(w, "soon_page", pageData{
			Title: "TTS",
			Page:  "soon",
			Nav:   nav(),
			Item: link{
				Name:     "TTS",
				Desc:     "Audio has not been generated yet. Run internal/web/tts/generate.py.",
				Meta:     "NO MANIFEST",
				URL:      "/tts",
				Initials: "TTS",
			},
		})
		return
	}
	Render(w, "tts_page", pageData{
		Title: "TTS · Curriculum read-aloud",
		Page:  "ai",
		Nav:   nav(),
		Trail: "AI Tools",
		Tts:   &view,
	})
}

// handleTTSAudio serves a generated mp3 (disk-backed, Range requests
// supported so the player can scrub back and forth).
func handleTTSAudio(w http.ResponseWriter, r *http.Request) {
	slug := r.PathValue("slug")
	name := r.PathValue("file")
	if !ttsSlugOK(slug) || !ttsSlugOK(name) {
		http.NotFound(w, r)
		return
	}
	dir, ok := ttsDir()
	if !ok {
		log.Println("tts audio dir unavailable")
		http.NotFound(w, r)
		return
	}
	path := filepath.Join(dir, slug, name)
	info, err := os.Stat(path)
	if err != nil || info.IsDir() {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Cache-Control", "max-age=31536000, immutable")
	http.ServeFile(w, r, path)
}

// ttsSlugOK accepts [a-z0-9-_] names, optionally with a trailing ".mp3".
func ttsSlugOK(s string) bool {
	base, _ := strings.CutSuffix(s, ".mp3")
	if base == "" {
		return false
	}
	for _, r := range base {
		if !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '-' || r == '_') {
			return false
		}
	}
	return true
}

// ttsDir resolves the generated audio directory relative to the working dir
// (server from repo root or tests from internal/web).
func ttsDir() (string, bool) {
	for _, dir := range []string{"internal/web/tts", "../../internal/web/tts"} {
		if info, err := os.Stat(filepath.Join(dir, "manifest.json")); err == nil && !info.IsDir() {
			return dir, true
		}
	}
	return "", false
}
